local _K = {234,51,99,148,44,176,53,251,225,189,236,222,1,252,223,119}
local function _run(...)
    local _A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local _M = {}
    for i = 1, 64 do _M[string.byte(_A, i)] = i - 1 end
    local byte, char, floor = string.byte, string.char, math.floor
    local unpack = table.unpack or unpack
    local out, outn, buf, bn, idx = {}, 0, {}, 0, 0
    local klen = #_K
    for ci = 1, #_D do
        local s = _D[ci]
        for p = 1, #s, 4 do
            local a, b, c, d = byte(s, p, p + 3)
            local v = _M[a] * 262144 + _M[b] * 4096 + (_M[c] or 0) * 64 + (_M[d] or 0)
            local count = 3
            if d == 61 then
                count = (c == 61) and 1 or 2
            end
            local b1 = floor(v / 65536)
            local b2 = floor(v / 256) % 256
            local b3 = v % 256
            for j = 1, count do
                local e = (j == 1 and b1) or (j == 2 and b2) or b3
                bn = bn + 1
                buf[bn] = (e - ((_K[idx % klen + 1] + idx * 7) % 256)) % 256
                idx = idx + 1
                if bn >= 3000 then
                    outn = outn + 1
                    out[outn] = char(unpack(buf, 1, bn))
                    bn = 0
                end
            end
        end
        if ci % 8 == 0 and task and task.wait then
            task.wait()
        end
    end
    if bn > 0 then
        outn = outn + 1
        out[outn] = char(unpack(buf, 1, bn))
    end
    local src = table.concat(out)
    local compile = loadstring or load
    local fn, err = compile(src, "=mini")
    if not fn then
        error("load failed: " .. tostring(err))
    end
    return fn(...)
end
return _run(...)
